import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def check_condition(n):
    if n <= 1:
        return False

    # We only need to check k such that 1 <= k < n and gcd(k, n) = 1
    for k in range(1, n):
        if gcd(k, n) == 1:
            if (k**2 - 1) % n != 0:
                return False
    return True

candidates = [2, 3, 4, 6, 8, 12, 24]
results = {}
for n in candidates:
    results[n] = check_condition(n)

print("Verification Results:")
for n, result in results.items():
    print(f"n={n}: {'PASS' if result else 'FAIL'}")

import math

def check_condition(n):
    if n < 2:
        return False

    k_coprime = [k for k in range(1, n) if math.gcd(k, n) == 1]

    if not k_coprime:
        # Only possible if n=1, but we restrict n >= 2
        return False

    for k in k_coprime:
        if (k * k - 1) % n != 0:
            print(f"Counterexample found for n={n}: k={k}. {k}^2 - 1 = {k*k - 1}, which is not divisible by {n}.")
            return False

    print(f"n={n} satisfies the condition.")
    return True

